import asyncio, concurrent.futures, threading
from langgraph.graph import StateGraph, START, END

class MCPToolSource:
    async def _serve(self):                      # the one task that owns the client
        async with Client(self.target) as client:
            self._ready.set_result(True)
            while (job := await self._queue.get()) is not None:
                future, fn = job
                try:
                    future.set_result(await fn(client))
                except BaseException as e:
                    future.set_exception(e)
    def _run(self, fn):                           # called from graph nodes (sync)
        future = concurrent.futures.Future()
        self._loop.call_soon_threadsafe(self._queue.put_nowait, (future, fn))
        return future.result(timeout=60)
    def call(self, name, arguments):
        return result_json(self._run(lambda c: c.call_tool(name, arguments)))

